"""The construct catalogue (b240, quote-23): `grammar/constructs.md`, generated by `model constructs --write` from
model_constructs_table and grammar 4 compiled in `grammar/corpus/constructs/`, is current; each example in it reads
as the catalogue says (the catalogue is part of the acceptance corpus); every function of the grammar is a
construct's, a word's or glue; and the catalogue cannot be written over an example that does not use its construct
or a function no construct covers."""
import pathlib
import re
import subprocess
import sys

import pytest

sys.path.insert(0, str(pathlib.Path(__file__).resolve().parents[1]))
import toolchain

REPO = pathlib.Path(__file__).resolve().parents[2]
sys.path.insert(0, str(REPO / "scripts"))
import model_constructs
import model_constructs_table

CATALOGUE = REPO / "grammar" / "constructs.md"
BLOCK = re.compile(r"^```construct\n(.*?)\n```$", re.MULTILINE | re.DOTALL)


@pytest.fixture(scope="module")
def grammar():
    toolchain.require()
    return model_constructs.Grammar()


def blocks():
    return [b.split("\n", 1) for b in BLOCK.findall(CATALOGUE.read_text())] if CATALOGUE.is_file() else []


def test_the_catalogue_is_current():
    toolchain.require()
    done = subprocess.run([sys.executable, str(REPO / "scripts" / "model"), "--root", str(REPO), "constructs",
                           "--check"], capture_output=True, text=True)
    assert done.returncode == 0, done.stdout + done.stderr
    assert done.stdout.strip() == "grammar/constructs.md is current"


def test_every_construct_has_its_block_and_the_person_s_codes_are_there():
    codes = re.findall(r"^## (\S+)$", CATALOGUE.read_text(), re.MULTILINE)
    assert codes == [e["code"] for e in model_constructs_table.CONSTRUCTS]
    assert {"rc-object", "not-response", "oblique-role"} <= set(codes)
    assert len(blocks()) == len(codes)


@pytest.mark.parametrize("line, said", blocks())
def test_each_example_of_the_catalogue_reads_as_it_says(grammar, line, said):
    _, reading, refusal = grammar.read(line)
    assert refusal is None
    assert reading == said


def test_every_function_of_the_grammar_is_a_construct_s_a_word_s_or_glue(grammar):
    assert model_constructs.uncovered(grammar.functions, grammar.frames) == []
    assert model_constructs.uncovered(grammar.functions + ["k_stage_Frob"], grammar.frames) == ["k_stage_Frob"]


def test_the_verbs_roles_are_read_off_their_frames(grammar):
    roles = {f.rsplit("_", 2)[0]: tags for f, tags in grammar.frames.items()}
    assert roles["e_give_action"] == {"object", "to"}
    assert roles["e_write_action"] == {"object"}
    assert {"oblique", "fixed"} <= set().union(*(t for f, t in grammar.frames.items() if f.startswith("e_exit")))


def test_an_example_that_does_not_use_its_construct_is_named(grammar, monkeypatch):
    bad = model_constructs_table.c("rc-frob", "a label", "a form", "DetEvery",
                                   "When a session ends a stage, `work` shall write a file.")
    monkeypatch.setattr(model_constructs, "CONSTRUCTS", model_constructs_table.CONSTRUCTS + [bad])
    _, problems = model_constructs.entries(grammar)
    assert problems == ["rc-frob's example does not use it"]


def test_a_refused_example_and_a_code_of_two_constructs_are_named(grammar, monkeypatch):
    bad = model_constructs_table.c("when", "a label", "a form", "When",
                                   "When a session ends a stage, `work` shall print the file.")
    monkeypatch.setattr(model_constructs, "CONSTRUCTS", model_constructs_table.CONSTRUCTS + [bad])
    _, problems = model_constructs.entries(grammar)
    assert problems[0] == "when is the code of two constructs"
    assert problems[1].startswith("when's example is refused: refused: \"the file\" has no antecedent")


def test_a_line_naming_a_code_cites_it(tmp_path):
    (tmp_path / "spec" / "capabilities").mkdir(parents=True)
    (tmp_path / "spec" / "capabilities" / "c.md").write_text(
        "- [r4] When the person runs `model parse` on a requirement that uses `rc-object`, `model` shall exit "
        "successfully.\n")
    assert model_constructs.citing(tmp_path) == {"rc-object": ["c#r4"]}
